// Generated by AI (UnitTest MCP)
use std::path::Path;

use rusqlite::params;

use crate::decay::ACTIVE_THRESHOLD;
use crate::error::{LodestarError, Result};

use super::{LodestarStore, ResetOutcome, Stats};

impl LodestarStore {
    pub fn stats(&self, now: i64) -> Result<Stats> {
        let active_goals: i64 = self.conn.query_row(
            "SELECT COUNT(1) FROM goals WHERE status = 'active'",
            [],
            |r| r.get(0),
        )?;
        let open_tasks: i64 = self.conn.query_row(
            "SELECT COUNT(1) FROM tasks WHERE status = 'open'",
            [],
            |r| r.get(0),
        )?;
        let claimed_tasks: i64 = self.conn.query_row(
            "SELECT COUNT(1) FROM tasks WHERE status = 'claimed'",
            [],
            |r| r.get(0),
        )?;
        let done_tasks: i64 = self.conn.query_row(
            "SELECT COUNT(1) FROM tasks WHERE status = 'done'",
            [],
            |r| r.get(0),
        )?;
        let total_tasks: i64 = self
            .conn
            .query_row("SELECT COUNT(1) FROM tasks", [], |r| r.get(0))?;
        let active_knowledge: i64 = self.conn.query_row(
                        "SELECT COUNT(1) FROM knowledge
                            WHERE retired_at IS NULL
                                AND effective_weight(weight, half_life_hours, confirmed_at, ?1) >= ?2",
            params![now, ACTIVE_THRESHOLD],
            |r| r.get(0),
        )?;
        Ok(Stats {
            active_goals,
            open_tasks,
            claimed_tasks,
            done_tasks,
            active_knowledge,
            total_tasks,
        })
    }

    /// Create a consistent SQLite backup while this store remains online.
    pub fn backup_database(&self, destination: &Path) -> Result<()> {
        mindleak_storage::backup_database(&self.conn, destination)?;
        Ok(())
    }

    /// Clear all durable intent only after the exact, plane-specific token.
    pub fn reset_database(&self, confirmation: &str) -> Result<ResetOutcome> {
        if confirmation != "RESET LODESTAR" {
            return Err(LodestarError::Invalid(
                "intent reset requires exact confirmation token: RESET LODESTAR".to_string(),
            ));
        }

        let transaction = self.conn.unchecked_transaction()?;
        let conformance_records_removed = transaction.execute("DELETE FROM conformance", [])?;
        let artifact_bindings_removed = transaction.execute("DELETE FROM goal_artifacts", [])?;
        let design_items_removed = transaction.execute("DELETE FROM design_items", [])?;
        let tasks_removed = transaction.execute("DELETE FROM tasks", [])?;
        let knowledge_removed = transaction.execute("DELETE FROM knowledge", [])?;
        transaction.execute("DELETE FROM policy_packs", [])?;
        // Declared context describes sessions of a fleet that no longer has any
        // work; leaving it would outlive everything it referred to.
        transaction.execute("DELETE FROM session_context", [])?;
        let goals_removed = transaction.execute("DELETE FROM goals", [])?;
        transaction.commit()?;

        Ok(ResetOutcome {
            goals_removed,
            tasks_removed,
            design_items_removed,
            artifact_bindings_removed,
            conformance_records_removed,
            knowledge_removed,
        })
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::db;
    use crate::design::{DesignMaterializationMode, DesignMaterializationPlan, DesignStatus};
    use crate::model::{ArtifactBindingMode, GoalKind, TaskStatus, Verdict};
    use crate::store::test_support::{goal, store, NOW};
    use crate::store::ConformanceAudit;

    #[test]
    fn stats_excludes_retired_knowledge_from_the_active_count() {
        let store = store();
        let retired = store
            .record_knowledge("retired lesson", "{}", 720.0, NOW)
            .unwrap();
        store
            .record_knowledge("active lesson", "{}", 720.0, NOW)
            .unwrap();
        store
            .retire_knowledge(&retired.id, "Reviewer", "measured false", None, NOW)
            .unwrap();

        assert_eq!(store.active_knowledge(NOW).unwrap().len(), 1);
        assert_eq!(store.stats(NOW).unwrap().active_knowledge, 1);
    }

    /// `open_tasks + claimed_tasks + done_tasks` omits blocked, in_review, and
    /// abandoned tasks -- it is not "every task", and a caller relying on it
    /// to answer "has anything ever been created here" gets a false negative
    /// the moment a task sits in one of those other statuses. `total_tasks`
    /// exists to answer that question directly.
    #[test]
    fn total_tasks_counts_every_status_not_just_open_claimed_and_done() {
        let store = store();
        let goal = goal(&store);
        store
            .create_task(&goal.id, "stays open one", "", None, NOW)
            .unwrap();
        store
            .create_task(&goal.id, "stays open two", "", None, NOW)
            .unwrap();
        let to_block = store
            .create_task(&goal.id, "gets blocked", "", None, NOW)
            .unwrap();
        store
            .block_task(
                &to_block.id,
                None,
                Some("waiting on a decision"),
                "Reviewer",
                NOW,
            )
            .unwrap();

        let stats = store.stats(NOW).unwrap();
        assert_eq!(stats.open_tasks, 2, "the two un-blocked tasks");
        assert_eq!(
            stats.total_tasks, 3,
            "every task, including the one blocking moved out of open"
        );
    }

    #[test]
    fn backup_database_preserves_constitution() {
        let store = store();
        let goal = goal(&store);
        let path =
            std::env::temp_dir().join(format!("lodestar-store-backup-{}.db", std::process::id()));
        let _ = std::fs::remove_file(&path);

        store.backup_database(&path).unwrap();

        let restored = LodestarStore::new(db::open(path.to_str().unwrap()).unwrap());
        assert_eq!(
            restored.get_goal(&goal.id).unwrap().unwrap().title,
            goal.title
        );
        drop(restored);
        std::fs::remove_file(path).unwrap();
    }

    #[test]
    fn reset_database_requires_exact_token_and_clears_durable_intent() {
        let store = store();
        let goal = goal(&store);
        let task = store
            .create_task(&goal.id, "Implement reset", "all state gone", None, NOW)
            .unwrap();
        store
            .link_goal_to_artifact(
                &goal.id,
                &["artifact:src/lib.rs".to_string()],
                ArtifactBindingMode::Governed,
            )
            .unwrap();
        store.claim_task(&task.id, "agent-a", 60, NOW).unwrap();
        store
            .record_conformance_and_transition(
                &task.id,
                "agent-a",
                ConformanceAudit {
                    evidence_schema_version: 1,
                    evidence: "{}",
                    verdict: Verdict::Aligned,
                    findings: "",
                },
                TaskStatus::Done,
                NOW,
            )
            .unwrap();
        store
            .record_knowledge("keep tests focused", "{}", 720.0, NOW)
            .unwrap();
        let design = store
            .register_design_item(
                "design:reset",
                "docs/adr/reset.md",
                "Reset",
                "no work",
                Some("planner"),
                NOW,
            )
            .unwrap();
        assert!(store
            .decide_design_item(&design.id, DesignStatus::Accepted, "reviewer", None, NOW,)
            .unwrap());
        store
            .materialize_design_item(
                &design.id,
                &DesignMaterializationPlan {
                    mode: DesignMaterializationMode::NoWork,
                    tasks: Vec::new(),
                    task_ids: Vec::new(),
                    constraints: Vec::new(),
                    rationale: Some("nothing to schedule".into()),
                },
                "reviewer",
                false,
                NOW,
            )
            .unwrap();

        assert!(store.reset_database("RESET MINDLEAK").is_err());
        assert!(store.get_goal(&goal.id).unwrap().is_some());

        let outcome = store.reset_database("RESET LODESTAR").unwrap();
        assert_eq!(outcome.goals_removed, 1);
        assert_eq!(outcome.tasks_removed, 1);
        assert_eq!(outcome.design_items_removed, 1);
        assert_eq!(outcome.artifact_bindings_removed, 1);
        assert_eq!(outcome.conformance_records_removed, 1);
        assert_eq!(outcome.knowledge_removed, 1);
        assert_eq!(store.stats(NOW).unwrap().active_goals, 0);
        assert!(store
            .list_design_items(None, false, false)
            .unwrap()
            .is_empty());
        assert!(store
            .define_goal(GoalKind::Objective, "New goal", "usable", None, NOW)
            .is_ok());
    }
}
